/* ---------------------------------------------------------------------------
 * 组件级样式：表格、固定列、骨架、进度扫光、上传错位字、勾选动画
 *
 * 手写 CSS，不在 theme.css 里 —— react-aria 的集合组件不能包一层，
 * 样式只能挂在它渲染出的原生元素上。
 * --------------------------------------------------------------------------- */

.dark .shadow-2xs {
  --tw-shadow: var(--shadow-2xs);
}

.dark .shadow-xs {
  --tw-shadow: var(--shadow-xs);
}

.dark .shadow-sm {
  --tw-shadow: var(--shadow-sm);
}

.dark .shadow-md {
  --tw-shadow: var(--shadow-md);
}

.dark .shadow-lg {
  --tw-shadow: var(--shadow-lg);
}

.dark .shadow-xl {
  --tw-shadow: var(--shadow-xl);
}

.dark .shadow-card {
  --tw-shadow: var(--shadow-card);
}

.dark .shadow-dropdown {
  --tw-shadow: var(--shadow-dropdown);
}

.dark .shadow-sidebar {
  --tw-shadow: var(--shadow-sidebar);
}

.dark .shadow-waitlist {
  --tw-shadow: var(--shadow-waitlist);
}

.t-stagger {
  --stagger-dur: 500ms;
  --stagger-distance: 12px;
  --stagger-stagger: 40ms;
  --stagger-blur: 3px;
  --stagger-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

.t-stagger-line {
  opacity: 0;
  transform: translateY(var(--stagger-distance));
  filter: blur(var(--stagger-blur));
  transition:
    opacity var(--stagger-dur) var(--stagger-ease),
    transform var(--stagger-dur) var(--stagger-ease),
    filter var(--stagger-dur) var(--stagger-ease);
  will-change: transform, opacity, filter;
}

.t-stagger-line--2 {
  transition-delay: var(--stagger-stagger);
}

.t-stagger-line--3 {
  transition-delay: calc(var(--stagger-stagger) * 2);
}

.t-stagger.is-shown .t-stagger-line {
  opacity: 1;
  transform: translateY(0);
  filter: blur(0);
}

.t-stagger.is-hiding .t-stagger-line {
  opacity: 0;
  transform: translateY(0);
  filter: blur(0);
  transition:
    opacity 200ms ease,
    transform 0s linear,
    filter 0s linear;
  transition-delay: 0s;
}

@media (prefers-reduced-motion: reduce) {
  .t-stagger-line {
    transition: none !important;
  }
}

@keyframes check-draw {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}

.animate-check-draw {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: check-draw 200ms cubic-bezier(0.65, 0, 0.35, 1) forwards;
}

@media (prefers-reduced-motion: reduce) {
  .animate-check-draw {
    animation: none;
    stroke-dashoffset: 0;
  }
}

.bui-table {
  @apply w-full text-left;

  border-collapse: separate;
  border-spacing: 0;
}

.bui-table th {
  @apply px-2.5 py-2.5 text-left align-middle text-body-medium text-text-tertiary whitespace-nowrap outline-none;
  background-color: var(--color-background-secondary-default);
  border-top: 1px solid var(--color-separator-border);
  border-bottom: 1px solid var(--color-separator-border);
  transition: padding 200ms ease, font-size 200ms ease;
}

.bui-table td {
  @apply px-2.5 py-2.5 align-middle text-body-medium text-text-primary outline-none;
  transition: padding 200ms ease, font-size 200ms ease;
}

.bui-table tbody tr:not(:last-child) > td {
  border-bottom: 1px solid var(--color-separator-border);
}

.bui-table tbody tr {
  @apply transition-colors duration-150;

  background-color: var(--color-background-primary-default);
}

.bui-table tbody tr[data-focus-visible] {
  @apply ring-2 ring-inset ring-border-focus-ring;
}

.bui-table tbody tr[data-selection-mode][data-hovered] {
  background-color: var(--color-background-secondary-hover);
}

.bui-table tbody tr[data-selection-mode][data-selected] {
  background-color: var(--color-accent-50);
}

.bui-sticky-col {
  position: sticky;
  right: 0;
  z-index: 1;
  background-color: inherit;
  border-left: 1px solid var(--color-separator-border);
}

.bui-sticky-col-head {
  z-index: 2;
}

.bui-table.bui-table-sm th,
.bui-table.bui-table-sm td {
  @apply px-2.5 py-1.5 text-body-2-medium;
}

@keyframes bui-progress-sweep {
  from {
    translate: -100% 0;
  }

  to {
    translate: 250% 0;
  }
}

.bui-skeleton {
  --bui-skeleton-line: rgb(255 255 255 / 0.9);
  --bui-skeleton-glow: rgb(255 255 255 / 0.55);
  --bui-skeleton-bloom: rgb(255 255 255 / 0.35);
  overflow: hidden;
  isolation: isolate;
}

.dark .bui-skeleton {
  --bui-skeleton-line: rgb(255 255 255 / 0.2);
  --bui-skeleton-glow: rgb(255 255 255 / 0.08);
  --bui-skeleton-bloom: rgb(255 255 255 / 0.04);
}

.bui-skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent, var(--bui-skeleton-line)) right / 2px 100% no-repeat,
    linear-gradient(90deg, transparent, var(--bui-skeleton-glow)) right / 72px 100% no-repeat,
    linear-gradient(90deg, transparent, var(--bui-skeleton-bloom)) right / 240px 100% no-repeat;
  translate: -100% 0;
  animation: bui-skeleton-sheen 2.2s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

.bui-skeleton:dir(rtl)::after {
  scale: -1 1;
  animation-direction: reverse;
}

@keyframes bui-skeleton-sheen {
  0% {
    translate: -100% 0;
  }

  60%,
  100% {
    translate: 100% 0;
  }
}
